pec() const { return fSpec; }		void SetTypeAndCreator( OSType inType, OSType inCreator );		// Misc Info "getters"		long GetSize();		OSErr GetErr() const { return fErr; }		void SetErr(OSErr err) { fErr = err; }		void ReportErr(const char* inMessage);protected:	static void CopySpec(FSSpec *dest, const FSSpec *src);	protected:	FSSpec 	fSpec;	short 	fRef;	OSErr 	fErr;	OSType 	fType;	OSType 	fCreator;};#endif/*	Historical Change Record:		----- R11 -----		07/11/96	initial implementation*/